## Tool Class — `ApiTools.cs`

```csharp
using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Fetches a resource by its unique identifier from the REST API.")]
    public async Task<string> GetResource(
        [Description("The unique identifier of the resource to fetch")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {Id}", id);
        var response = await httpClient.GetAsync($"/api/resources/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("Lists all resources, optionally filtered by category.")]
    public async Task<string> ListResources(
        [Description("Optional category to filter results")] string? category = null,
        CancellationToken cancellationToken = default)
    {
        var url = category is null ? "/api/resources" : $"/api/resources?category={category}";
        logger.LogInformation("Listing resources with category={Category}", category);
        return await httpClient.GetStringAsync(url, cancellationToken);
    }

    [McpServerTool(Destructive = true), Description("Creates a new resource with the given name and content.")]
    public async Task<string> CreateResource(
        [Description("Name for the new resource")] string name,
        [Description("Content body of the resource")] string content,
        CancellationToken cancellationToken = default)
    {
        var payload = JsonSerializer.Serialize(new { name, content });
        var response = await httpClient.PostAsync("/api/resources",
            new StringContent(payload, System.Text.Encoding.UTF8, "application/json"),
            cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}
```

